SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    class PostHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('Content-Type')
            if not content_type or 'application/json' not in content_type:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response_msg = {'error': 'Content-Type header is not application/json'}
                self.wfile.write(json.dumps(response_msg).encode())
                return

            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length)

            try:
                data = json.loads(post_data)
            except json.JSONDecodeError:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response_msg = {'error': 'Invalid JSON'}
                self.wfile.write(json.dumps(response_msg).encode())
                return

            if 'data' not in data:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response_msg = {'error': 'No data key in request'}
                self.wfile.write(json.dumps(response_msg).encode())
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode())

    return PostHandler

