from collections import defaultdict
import json
import csv
# Constants
def task_func(input_file, output_file):
    with open(input_file, 'r') as f:
        data = json.load(f)

    stats = defaultdict(list)
    for item in data:
        for key, value in item.items():
            stats[key].append(value)

    result = {}
    for key, values in stats.items():
        result[key] = {
            'mean': np.mean(values),
            'median': np.median(values)
        }

    with open(output_file, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['key', 'mean', 'median'])
        for key, vals in result.items():
            writer.writerow([key, vals['mean'], vals['median']])

    return result

import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if not isinstance(json_data, list) or len(json_data) == 0:
        raise ValueError("JSON data must be a non-empty list.")

    countries = []
    populations = []

    for item in json_data:
        if not isinstance(item, dict):
            raise ValueError("Each item in JSON data must be a dictionary.")

        if 'Country' not in item or 'Population' not in item:
            raise ValueError("Missing required fields 'Country' or 'Population'.")

        country = item['Country']
        population = item['Population']

        if not isinstance(country, str):
            raise ValueError("Country name must be a string.")

        if not isinstance(population, (int, float)):
            raise ValueError("Population must be a numeric value.")

        if population < 0:
            raise ValueError("Population cannot be negative.")

        countries.append(country)
        populations.append(math.floor(population))

    df = pd.DataFrame({'Country': countries, 'Population': populations})

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write file to {file_path}: {str(e)}")

    return os.path.abspath(file_path), df

